def fibonacci(n):
    """Computes the n-th Fibonacci number."""
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# Compute F2 through F17
fib_list = [fibonacci(i) for i in range(2, 18)]
print(f"F2 to F17: {fib_list}")

def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# We need F_2 through F_21
F = {}
for k in range(2, 22):
    F[k] = fibonacci(k)

fib_diffs = [F[k] for k in range(2, 22)]
print("Fibonacci differences F_2 through F_21:")
print(fib_diffs)

# Test small candidate sets S
# Try |S| = 5, as 5*4 = 20.
# A good starting point for difference sets is often a sequence of numbers that are far apart, or related to powers of 2, but let's try simple integers first and see.

# Since the differences grow quickly (up to 10946), the elements of S must span a range of at least 10946.

# A heuristic construction often involves placing elements of S such that the differences they generate cover the required gaps efficiently.

# Let's try to construct S iteratively.
# S = {s1, s2, s3, s4, s5}

# To cover F_2=1, F_3=2, F_4=3, F_5=5, ...

# Let's try S = {0, 1, 3, 7, 15} (related to powers of 2, which often works well for covering differences)
S1 = [0, 1, 3, 7, 15]
differences1 = set()
for i in range(len(S1)):
    for j in range(len(S1)):
        if i != j:
            differences1.add(S1[i] - S1[j])

print("\nTesting S1 = {0, 1, 3, 7, 15}:")
print("Generated differences:", sorted(list(differences1)))

# Check if all target differences are present in S1
required_diffs = set(fib_diffs)
covered_diffs_S1 = set(d for d in differences1 if d > 0)

missing_diffs_S1 = required_diffs - covered_diffs_S1

print("\nCheck S1:")
if missing_diffs_S1:
    print(f"Missing differences: {sorted(list(missing_diffs_S1))}")
else:
    print("S1 covers all required positive differences.")

